public void onWalletDebitCommand(DebitCommand cmd) {
    // Step 1: Check balance
    if (wallet.getBalance() < cmd.getAmount()) {
        throw new InsufficientFundsException();
    }
    // Step 2: Deduct amount
    wallet.setBalance(wallet.getBalance() - cmd.getAmount());
    walletRepository.save(wallet);
    // Step 3: Publish event
    eventBus.publish(new WalletDebitedEvent(cmd.getOrderId()));
}
